Point2f ConcentricSampleDisk(const Point2f &u) {
    // Map uniform random numbers to [0,1]^2 on unit disk using Shirley and Chiu's
    // concentric mapping.  This gives better sample distribution than the
    // radial mapping mentioned on p. 207 of the third edition.
    float phi = 2 * u[0] - 1;
    float r = u[1];
    if (phi >= r) {
        if (phi > -r) {
            // (phi, r) is inside circle centered at (+X, +Y)
            float d = phi + r; // (phi, r) is (1,0) -> d=1, (0,1) -> d=1
            return Point2f(d * (1 - phi * phi / 4), d * r);
        } else {
            // (phi, r) is inside circle centered at (-X, -Y)
            float d = phi - r; // (phi, r) is (-1,0) -> d=-1, (0,1) -> d=-1
            return Point2f(d * (1 - phi * phi / 4), d * r);
        }
    } else {
        if (phi >= -r) {
